import { describe, expect, it } from 'vitest'
import { withLine } from '../../scripts/issue-note-line.mjs'

// The notes comments of a spec issue („For the Release PR“, „Waiting for the user“) are edited in place as a run goes
// (docs/agents/delivery.md § Issues). In 0.18 an appended line landed below the comment's „Generated by“ footer, and a
// second script had to move it (#833).
const FOOTER = '---\n_Generated by [Claude Code](https://claude.ai/code)_'
const notes = [
  '## For the Release PR',
  '',
  '**Lists:** Closes #961; Refs #962.',
  '',
  '**Asks the user for:**',
  '- the production migration of #957;',
  '',
  '**Review notes not fixed:**',
  '- the button is built twice;',
  '',
  FOOTER,
].join('\n')

describe('withLine', () => {
  it('puts the line above the footer when no section is named', () => {
    expect(withLine(notes, '- #964: walk-through approved.')).toMatch(/- the button is built twice;\n- #964: walk-through approved\.\n\n---\n_Generated by .*_$/)
  })

  it('puts the line at the end of the named section', () => {
    const text = withLine(notes, '- the deploy while no Session runs.', 'Asks the user for')
    expect(text).toContain('- the production migration of #957;\n- the deploy while no Session runs.\n\n**Review notes not fixed:**')
  })

  it('appends to a comment without a footer', () => {
    expect(withLine('## Waiting for the user\n\n- #771: the four Emote sounds.', '- #779: the walk-through.')).toBe('## Waiting for the user\n\n- #771: the four Emote sounds.\n- #779: the walk-through.')
  })

  it('opens a section that is not there yet, above the footer', () => {
    const text = withLine(notes, '- #958: closed with the walk-through.', 'Closed by hand')
    expect(text).toContain('- the button is built twice;\n\n**Closed by hand:**\n- #958: closed with the walk-through.\n\n---')
  })
})
